Owner closure admission and exact authoritative output-root selection are separate prerequisites.
Disagreement is the identity CompleteReplayMismatch condition carrying the exact comparison key.
"""
if not C.equal_typed(actual,expected['proof']):raise M.CompleteReplayMismatch('EVALUATOR_COMPLETE_PROOF_REPLAY')
for key,value in expected['objects'].items():
    if not C.equal_typed(objects.get(key),value):raise M.CompleteReplayMismatch('EVALUATOR_COMPLETE_OBJECT_REPLAY:'+key)
for key,value in expected['blobs'].items():
    if blobs.get(key)!=value:raise M.CompleteReplayMismatch('EVALUATOR_COMPLETE_BLOB_REPLAY:'+key)
return True

run=self.runs[rid]
# Verified restoration is a retained regeneration boundary; replay disagreement is its carrier.
try:closed=close_run(run,objects,blobs)
except CompleteReplayMismatch as exc:raise RegenerationMismatch(rid) from exc
if closed!=rid:raise RegenerationMismatch(rid)

